# 가상 DNS 레코드: CNAME 이 가리키는 곳이 아직 우리 것인가
records = [
    ("promo.example.com", "CNAME", "example-promo.s3-website.ap-northeast-2.amazonaws.com"),
    ("blog.example.com", "CNAME", "example.github.io"),
    ("api.example.com", "A", "203.0.113.10"),
]
our_buckets = {"example-static"}      # 계정에 실제로 있는 버킷
our_pages = {"example.github.io"}     # 조직이 가진 Pages

for name, rtype, target in records:
    if rtype != "CNAME":
        continue
    if ".s3-website." in target:
        ok = target.split(".s3-website.")[0] in our_buckets
    elif target.endswith(".github.io"):
        ok = target in our_pages
    else:
        ok = True
    print(name, "->", target, "|", "정상" if ok else "주인 없음: 탈취 위험")

# 노출 자산 우선순위: 악용 확인(KEV)·악용 확률(EPSS)·심각도(CVSS)·업무 중요도(1~3) — 가중치는 예시
assets = [
    ("pay-admin.example.com", 7.5, 0.02, False, 3),
    ("test-wiki.example.com", 9.8, 0.94, True, 1),
    ("img.example.com", 5.3, 0.01, False, 1),
]

def score(cvss, epss, kev, crit):
    s = cvss / 10 * 40 + epss * 30 + (30 if kev else 0)
    return round(s * (1 + 0.5 * (crit - 1)), 1)

for host, *v in sorted(assets, key=lambda a: score(*a[1:]), reverse=True):
    print(host, score(*v))
